const initialJournal=[
 {slug:'finding-your-signature-scent',title:'Finding your signature scent',date:'2026-09-24T09:00:00.000Z',category:'Scent Stories',excerpt:'Follow the notes you love, then give a fragrance time to tell its story.',image:'/assets/hero-perfume.webp',published:true,body:'## Start with what you already love\nA cup of white tea, the warmth of vanilla, a fresh bouquet. Familiar aromas are a useful starting point when exploring fragrance.\n\n## Meet the fragrance slowly\nTry one scent at a time. Notice the opening, then return to it after it has settled. Your favorite part may arrive later.\n\n## Make it personal\nThere is no single perfect choice for everyone. Choose the fragrance you enjoy wearing, and let your collection grow with your days.'},
 {slug:'a-guide-to-fragrance-notes',title:'A little guide to fragrance notes',date:'2026-09-20T09:00:00.000Z',category:'Scent Guide',excerpt:'From the first impression to the lingering finish, discover the layers in a bottle.',image:'/assets/atelier-story.webp',published:true,body:'## The first impression\nTop notes introduce a fragrance. They often feel bright and immediately noticeable.\n\n## The heart of the scent\nAs the opening softens, heart notes become more apparent. Florals, gentle spices and aromatic notes often give a scent its character.\n\n## The lasting impression\nBase notes create depth. Woods, amber and musk can feel warmer and more settled. The way you experience these layers will vary from person to person.'},
 {slug:'small-rituals-for-everyday-fragrance',title:'Small rituals, beautiful everyday moments',date:'2026-09-16T09:00:00.000Z',category:'Everyday Rituals',excerpt:'Turn a familiar morning into a small moment that belongs to you.',image:'/assets/hero-perfume.webp',published:true,body:'## A moment before the day begins\nChoose a fragrance that suits your mood. A light citrus can feel bright; a soft musk can feel calm and familiar.\n\n## Keep it considered\nStart lightly and adjust to your preference. Be mindful of shared spaces and other people around you.\n\n## Enjoy the ritual\nA favorite scent can be a personal finishing touch. Keep your bottle somewhere you will remember to enjoy it.'},
 {slug:'choosing-a-thoughtful-fragrance-gift',title:'Choosing a thoughtful fragrance gift',date:'2026-09-12T09:00:00.000Z',category:'Gifting',excerpt:'A few thoughtful questions can make a fragrance gift feel wonderfully personal.',image:'/assets/atelier-story.webp',published:true,body:'## Think about their favorites\nDo they enjoy fresh florals, warm woods or a clean, understated scent? Their existing favorites can offer helpful clues.\n\n## Choose the mood\nConsider whether the gift is for everyday wear, a special evening or a new chapter. Keep the recipient at the center of the choice.\n\n## Add a personal note\nTell them why you chose it. If you need help exploring the collection, send our studio an inquiry.'},
 {slug:'inside-the-aurea-studio',title:'Inside the Auréa fragrance studio',date:'2026-09-08T09:00:00.000Z',category:'Behind the Bottle',excerpt:'A look at the colors, textures and quiet inspiration behind our collection.',image:'/assets/atelier-story.webp',published:true,body:'## Inspired by the everyday\nSoft silk, fresh petals and the golden light of late afternoon inform the mood of Auréa. Each concept begins with a feeling we want to capture.\n\n## A collection of contrasts\nOur fragrance concepts range from airy citrus and white musk to warm amber and deeper woods. We believe there is room for more than one signature.\n\n## Your next chapter\nExplore the collection and tell us which notes speak to you. The best place to begin is with a little curiosity.'}
].map((entry,index)=>({...entry,image:'/assets/journal-faq-v2.webp#frame='+index}));

const escape=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
function markdown(body){const inline=text=>escape(text).replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*\n]+)\*/g,'<em>$1</em>').replace(/\[([^\]\n]+)\]\((https?:\/\/[^\s)]+|\/[a-zA-Z0-9\/_?=&%-]*)\)/g,'<a href="$2" rel="noopener noreferrer">$1</a>');return String(body).split(/\n\s*\n/).map(block=>{const lines=block.split('\n');if(/^#{1,3} /.test(lines[0])){const level=lines[0].startsWith('### ')?3:2;const title=lines.shift().replace(/^#{1,3} /,'');return `<h${level}>${inline(title)}</h${level}>${lines.length?'<p>'+inline(lines.join('\n')).replace(/\n/g,'<br>')+'</p>':''}`;}if(lines.every(line=>/^[-*] /.test(line)))return '<ul>'+lines.map(line=>'<li>'+inline(line.slice(2))+'</li>').join('')+'</ul>';if(lines.every(line=>/^\d+\. /.test(line)))return '<ol>'+lines.map(line=>'<li>'+inline(line.replace(/^\d+\. /,''))+'</li>').join('')+'</ol>';if(lines.every(line=>line.startsWith('> ')))return '<blockquote>'+inline(lines.map(line=>line.slice(2)).join('\n')).replace(/\n/g,'<br>')+'</blockquote>';return `<p>${inline(block).replace(/\n/g,'<br>')}</p>`;}).join('');}
const icons={search:'<circle cx="10" cy="10" r="6.5"/><path d="m15 15 5 5"/>',sparkle:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>',bottle:'<path d="M8 2h8v5H8ZM6 7h12v15H6Z"/><path d="M9 13h6M9 16h6"/>',message:'<path d="M3 3h18v14H8l-5 4Z"/><path d="M7 8h10M7 12h7"/>',leaf:'<path d="M20 3C7 1 2 8 5 15s16 5 15-12Z"/><path d="m4 21 11-13"/>',gift:'<path d="M3 9h18v4H3ZM5 13v9h14v-9M12 9v13"/><path d="M12 9C4 9 5 1 9 3l3 6c8 0 7-8 3-6Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 3"/>',truck:'<path d="M2 4h12v13H2ZM14 8h5l3 5v4h-8"/><circle cx="6" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',phone:'<path d="m5 2 4 5-2 3c2 4 4 6 7 7l3-2 5 4c-2 7-12 2-17-5S0 3 5 2Z"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3Z"/>'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.sparkle}</svg>`;
const money=price=>'₱'+Number(price).toLocaleString('en-PH');
const bottle=(product,cls='',photo=product.photo||{src:'/assets/perfume-atlas.webp',frame:product.image})=>`<div class="bottle-image ${cls}" role="img" aria-label="Auréa ${escape(product.name)} perfume bottle" data-photo-key="${escape(photo.src)}:${photo.frame}" style="--col:${photo.frame%3};--row:${Math.floor(photo.frame/3)}"><img src="${escape(photo.src)}" width="1536" height="1024" loading="lazy" alt=""></div>`;
function editorialImage(src,label,cls=''){const frame=String(src).match(/#frame=([0-5])$/);return frame?`<div class="editorial-frame ${cls}">${bottle({name:label},'',{src:src.split('#')[0],frame:Number(frame[1])})}</div>`:`<img class="${cls}" src="${escape(src)}" width="1536" height="1024" loading="lazy" alt="${escape(label)}">`;}
function productCard(product,context='catalog'){return `<article class="product-card" data-family="${product.family}" data-collection="${product.collection}" data-price="${product.price}" data-name="${escape(product.name)}">${bottle(product,'',context==='home'?product.homePhoto:product.photo)}<div class="product-copy"><h3>${escape(product.name)}</h3><p>${product.concentration} · 50 mL</p><strong>${money(product.price)}</strong><span class="product-notes">${escape(product.notes.slice(0,2).join(' · '))}</span><a class="button product-inquiry" data-contact-action href="/contact?fragrance=${product.id}">Inquire About This Scent</a></div></article>`;}
function journalCard(entry,mode='full'){return `<article class="journal-card ${mode==='text'?'no-photo':''}"><a href="/journal/${encodeURIComponent(entry.slug)}">${mode==='text'?'':editorialImage(entry.image,entry.title)}<div class="journal-copy"><span class="eyebrow">${escape(entry.category)}</span><h3>${escape(entry.title)}</h3><p>${escape(entry.excerpt)}</p><span class="text-link">Read the story</span></div></a></article>`;}
function header(current){const nav=[['/','Home'],['/fragrances','Fragrances'],['/scent-guide','Scent Guide'],['/about','Our Story'],['/journal','Journal'],['/faq','FAQs'],['/contact','Contact']];return `<div class="announcement">${icon('sparkle')} A little luxury. A scent that feels like you.</div><header class="site-header"><a class="brand" href="/" aria-label="Auréa Parfums home"><span>AURÉA</span><small>PARFUMS</small></a><nav id="main-nav" class="main-nav" aria-label="Main navigation">${nav.map(([href,label])=>`<a href="${href}" ${current===href?'aria-current="page"':''}>${label}</a>`).join('')}</nav><a class="header-search" href="/fragrances#catalog-search" aria-label="Search fragrances">${icon('search')}</a><a class="button button-outline header-inquiry" href="/contact" data-contact-action>Find My Scent</a><button class="nav-toggle" type="button" aria-controls="main-nav" aria-expanded="false" aria-label="Open navigation"><span></span><span></span><span></span></button></header>`;}
function footer(){return `<footer class="site-footer"><div><a class="brand" href="/"><span>AURÉA</span><small>PARFUMS</small></a><p>Fragrance for the moments<br>that become your story.</p></div><div><h2>Discover</h2><a href="/fragrances">Our fragrances</a><a href="/scent-guide">Find your fragrance family</a><a href="/journal">The Scent Journal</a></div><div><h2>Let’s Connect</h2><a href="/contact" data-contact-action>Ask about a fragrance</a><a href="/faq">Questions &amp; answers</a><button type="button" class="link-button demo-contact" data-channel="Instagram">Instagram</button><button type="button" class="link-button demo-contact" data-channel="Facebook">Facebook</button></div><div><h2>Behind the Bottle</h2><a href="/about">Our story</a><a href="/admin/">Journal editor</a><p class="footer-note">A fictional perfume business<br>created as a portfolio prototype.</p></div><p class="copyright">© 2026 Auréa Parfums. All rights reserved.</p></footer><dialog id="contact-demo" class="small-dialog" aria-labelledby="demo-title"><button type="button" class="dialog-close" aria-label="Close">×</button><h2 id="demo-title">Connect with Auréa</h2><p>This portfolio prototype uses fictional business details. This link can be connected to the final business’s approved contact or social account.</p><a class="button" href="/contact">Send a Website Inquiry</a></dialog>`;}
const benefits=`<div class="benefit-strip"><div>${icon('bottle')}<span><strong>Considered fragrance</strong><small>Notes for every mood</small></span></div><div>${icon('truck')}<span><strong>Delivery inquiries</strong><small>Ask about your location</small></span></div><div>${icon('gift')}<span><strong>Thoughtful gifting</strong><small>A personal finishing touch</small></span></div><div>${icon('message')}<span><strong>Here to help</strong><small>Find your next favorite</small></span></div></div>`;
const heading=(label,title,text='')=>`<div class="page-heading"><span class="eyebrow">${label}</span><h1>${title}</h1>${text?`<p>${text}</p>`:''}<span class="gold-line"></span></div>`;
function home(entries=initialJournal){return `<section class="hero"><img class="hero-photo" src="/assets/hero-perfume.webp" width="1536" height="1024" alt="Rose-colored Auréa perfume on marble beside peonies"><div class="hero-copy"><span class="script-label">A fragrance, a feeling, a little you.</span><h1>Find your<br>signature scent.</h1><p>Beautiful fragrance for everyday moments.<br>Soft florals. Warm woods. Something uniquely yours.</p><div class="hero-buttons"><a class="button" href="/fragrances">Explore Fragrances</a><a class="button button-outline" href="/scent-guide">Discover Your Notes</a></div></div></section>${benefits}<section class="section-pad"><div class="section-title"><h2>The Signature Collection</h2><span></span><p>Meet the scents that make an impression.</p></div><div class="products-grid home-products">${fragrances.slice(0,5).map(product=>productCard(product,'home')).join('')}</div></section><section class="gift-banner"><div>${icon('gift')}<span><h2>A little thought. A lovely gift.</h2><p>Let us help you choose a scent for someone special.</p></span></div><a class="button" href="/contact?fragrance=gift-selection" data-contact-action>Ask About Gifting</a></section><section class="section-pad journal-home"><div class="section-title"><h2>From the Scent Journal</h2><span></span><p>Stories, notes, and small fragrance rituals.</p></div><div class="journal-grid">${entries.slice(0,3).map(entry=>journalCard(entry,'text')).join('')}</div><a class="text-link section-more" href="/journal">Explore the journal</a></section>`;}
function catalog(){return `${heading('The fragrance wardrobe','Our Fragrances','Explore the notes, find your favorites, and ask us about the scent that speaks to you.')}<div class="catalog-layout section-pad"><aside class="catalog-filters"><h2>Collections</h2><div class="filter-options" id="collection-filters">${['All','Women','Men','Unisex'].map((name,i)=>`<button type="button" data-collection-filter="${name}" class="${i===0?'active':''}">${name==='All'?'All Fragrances':name+"’s Fragrances"}<span>${name==='All'?fragrances.length:fragrances.filter(p=>p.collection===name).length}</span></button>`).join('')}</div><h2>Scent Family</h2>${['Floral','Fresh','Woody','Citrus','Amber'].map(family=>`<label class="filter-check"><input type="checkbox" name="family" value="${family}">${family}</label>`).join('')}<h2>Maximum Price</h2><label class="price-filter"><span id="price-label">₱900</span><input type="range" id="price-filter" min="400" max="900" step="50" value="900" aria-label="Maximum fragrance price"></label><button class="text-link clear-filters" type="button">Clear filters</button></aside><div class="catalog-main"><div class="catalog-controls"><label class="search-field">${icon('search')}<input id="catalog-search" type="search" placeholder="Search fragrances or notes…" aria-label="Search fragrances or notes"></label><label class="sort-field"><span>Sort by</span><select id="catalog-sort"><option value="featured">Featured</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="name">Name: A to Z</option></select></label></div><p id="catalog-count" class="catalog-count" aria-live="polite">Showing ${fragrances.length} fragrances</p><div class="products-grid catalog-products">${fragrances.map(productCard).join('')}</div><p id="catalog-empty" hidden class="empty-state">No fragrances match your selection. Try another note or clear your filters.</p></div></div>${benefits}`;}
function about(){return `${heading('Behind the bottle','Fragrance, made personal.','A collection inspired by beautiful textures, everyday rituals, and the stories we carry.')}<section class="story-layout section-pad"><img src="/assets/atelier-story.webp" width="1536" height="1024" alt="Perfume bottle, blending tools and petals at the Auréa fragrance studio"><div><span class="eyebrow">The Auréa feeling</span><h2>A little luxury.<br>A very personal story.</h2><p>We believe fragrance is a personal finishing touch. It can be bright and playful, warm and familiar, or quietly captivating.</p><p>Auréa brings those moods together in a considered collection. Explore soft florals, airy musks, luminous citrus, and deeper woods, then choose the one that feels like you.</p><a class="button button-outline" href="/fragrances">Meet the Collection</a></div></section><section class="values-grid section-pad">${[['bottle','Beautifully considered','Explore the personality of each fragrance through its notes and character.'],['gift','Thoughtfully chosen','For yourself or someone special, choose a scent with a personal story.'],['message','A little guidance','Tell us what you enjoy. We can help you explore the collection.']].map(([symbol,title,text])=>`<article>${icon(symbol)}<h2>${title}</h2><p>${text}</p></article>`).join('')}</section>`;}
function guide(){const families=[['Floral','Petals, blooms & soft elegance','Rose Velvet, Golden Bloom, Petal Silk',0],['Fresh','Clean, airy & understated','Pure Musk, Moonlit Linen',1],['Woody','Depth, warmth & quiet confidence','Noir Woods, Ebony Oud',2],['Citrus','Bright, sparkling & uplifting','Citrus Muse, Sunlit Neroli',3],['Amber','Smooth, warm & softly enveloping','Amber Veil, Velvet Amber',4]];return `${heading('Discover your notes','Your guide to a beautiful scent.','Start with a feeling. Follow the fragrance family that draws you in.')}<section class="scent-family-grid section-pad">${families.map(([family,description,examples,image])=>`<article>${bottle({name:family,photo:{src:'/assets/guide-contact-v2.webp',frame:image}})}<div><span class="eyebrow">${family}</span><h2>${description}</h2><p>${examples}</p><a class="text-link" href="/fragrances?family=${family}">Explore ${family.toLowerCase()} scents</a></div></article>`).join('')}</section><section class="notes-panel section-pad"><h2>A fragrance unfolds in layers.</h2><div><article><span>01</span><h3>The opening</h3><p>The first impression: often bright, fresh, and immediately noticeable.</p></article><article><span>02</span><h3>The heart</h3><p>The character of the fragrance as its opening begins to soften.</p></article><article><span>03</span><h3>The base</h3><p>The quieter, deeper notes that shape the settled impression.</p></article></div></section>`;}
function faq(){return `${heading('A little clarity','Questions, answered.','Helpful details before you choose your next fragrance.')}<div class="faq-layout section-pad"><aside>${editorialImage('/assets/journal-faq-v2.webp#frame=5','Scent blotters and Auréa fragrances','faq-photo')}<h2>Need a personal recommendation?</h2><p>Tell us the notes you enjoy and the mood you have in mind.</p><a class="button" href="/contact" data-contact-action>Ask the Studio</a></aside><div class="faq-list">${[['How do I choose a fragrance?','Start with your favorite fragrance family. Our Scent Guide introduces floral, fresh, woody, citrus and amber notes. If you would like help, send us an inquiry.'],['What sizes are shown in the collection?','The catalog features 50 mL bottles. Each listing shows its concentration and sample price.'],['Can I ask about a fragrance gift?','Yes. Tell us who the gift is for and a little about their preferences using the single inquiry form.'],['How can I ask about delivery?','Include your city or province in your message. The studio can confirm available delivery options when the business is connected for a real launch.'],['How should I store perfume?','Keep the bottle closed and away from direct sunlight or unnecessary heat. Follow any care guidance supplied with your fragrance.'],['Can I buy directly through this website?','This website is a fragrance catalog. Use the inquiry form to ask about a scent, availability or gifting.']].map(([question,answer])=>`<details><summary>${question}<span aria-hidden="true">+</span></summary><p>${answer}</p></details>`).join('')}</div></div>`;}
function contact(){return `${heading('We’re here to help','Let’s find your next favorite.','Tell us what you love, ask about a fragrance, or plan a thoughtful gift.')}<div class="contact-layout section-pad"><aside class="contact-story">${editorialImage('/assets/guide-contact-v2.webp#frame=5','Auréa discovery fragrances and gift packaging','contact-photo')}<div><h2>Made for your story.</h2><p>Online fragrance studio · Philippines<br>Monday–Saturday · 9 AM–6 PM</p><div class="contact-links"><button type="button" class="demo-contact" data-channel="Phone">${icon('phone')}Call the Studio</button><button type="button" class="demo-contact" data-channel="WhatsApp">${icon('message')}Message the Studio</button></div></div></aside><form id="inquiry-form"><h2>Send an inquiry</h2><p class="form-intro">The more you tell us, the easier it is to help you explore the collection.</p><div class="field-row"><label>Your Name<input name="name" autocomplete="name" required maxlength="80" placeholder="Full name"></label><label>Email Address<input name="email" type="email" autocomplete="email" required maxlength="120" placeholder="you@example.com"></label></div><label>What Are You Interested In?<select name="interest" required><option value="">Choose a fragrance or topic</option value="recommendation">A fragrance recommendation</option value="gift-selection">A fragrance gift</option>${fragrances.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}<option value="delivery">Delivery information</option></select></label><label>Your Message<textarea name="message" required minlength="10" maxlength="2000" rows="5" placeholder="Your favorite notes, questions, or the gift you have in mind…"></textarea></label><label class="honeypot" aria-hidden="true">Website<input name="website" autocomplete="off" tabindex="-1"></label><label class="privacy-check"><input type="checkbox" name="consent" required> I agree to share these details so the studio can respond to my inquiry.</label><button class="button" type="submit">Send Inquiry</button><p id="form-status" class="form-status" role="status"></p><p class="form-note">Prototype inquiries are saved for the site owner. They are not emailed to a real perfume business.</p></form></div>`;}
function journal(entries){return `${heading('Stories from the studio','The Scent Journal','Fragrance notes, everyday rituals, and thoughtful ideas for finding your favorite.')}<section class="journal-grid journal-list section-pad">${entries.map(journalCard).join('')||'<p class="empty-state">The next scent story is on its way.</p>'}</section>`;}
function article(entry){return `<article class="article-page"><div class="article-heading"><a class="text-link" href="/journal">The Scent Journal</a><span class="eyebrow">${escape(entry.category)}</span><h1>${escape(entry.title)}</h1><p>${escape(entry.excerpt)}</p><time datetime="${escape(entry.date)}">${new Date(entry.date).toLocaleDateString('en-PH',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Manila'})}</time></div>${editorialImage(entry.image,entry.title,'article-cover')}<div class="article-body">${markdown(entry.body)}<div class="article-next"><h2>Find the notes that feel like you.</h2><a class="button button-outline" href="/fragrances">Explore Fragrances</a></div></div></article>`;}
function renderPage(path,entries=initialJournal,origin='https://aurea-parfums-premium.herrishuie.chatgpt.site'){
 const pages={'/':['Home','Beautiful perfume concepts and scent stories.',()=>home(entries)],'/fragrances':['Our Fragrances','Explore twelve perfume concepts by fragrance family, collection and price.',catalog],'/about':['Our Story','The textures, feelings and everyday rituals behind Auréa Parfums.',about],'/scent-guide':['Scent Guide','Explore floral, fresh, woody, citrus and amber fragrance families.',guide],'/faq':['FAQs','Helpful fragrance and inquiry questions, answered.',faq],'/contact':['Contact','Send the Auréa studio a fragrance, gifting or delivery inquiry.',contact],'/journal':['The Scent Journal','Fragrance notes, rituals and scent stories from Auréa Parfums.',()=>journal(entries)]};
 let page=pages[path],current=path;
 if(path.startsWith('/journal/')){const entry=entries.find(e=>e.slug===decodeURIComponent(path.slice(9)));if(entry){page=[entry.title,entry.excerpt,()=>article(entry)];current='/journal';}}
 if(!page)return null;
 const [title,description,body]=page;
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escape(title)} — Auréa Parfums</title><meta name="description" content="${escape(description)}"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#be6977"><link rel="canonical" href="${origin+path}"><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"><link rel="stylesheet" href="/styles.css"><script src="/site-config.js"></script><script src="/app.js" defer></script></head><body><a href="#main" class="skip-link">Skip to content</a>${header(current)}<main id="main">${body()}</main>${footer()}</body></html>`;
}

const json=(value,status=200)=>new Response(JSON.stringify(value),{status,headers:{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
const legacyCovers=['/assets/hero-perfume.webp','/assets/atelier-story.webp'];
const covers=[...legacyCovers,...initialJournal.map(entry=>entry.image)];
const pathFor=slug=>'content/journal/'+slug+'.json';
const safePath=path=>/^content\/journal\/[a-z0-9][a-z0-9-]{0,99}\.json$/.test(path);
async function seed(db){const done=await db.prepare("SELECT value FROM editor_settings WHERE key='journal_seeded'").first();if(done)return;await db.batch([...initialJournal.map(entry=>db.prepare("INSERT OR IGNORE INTO journal_entries(path,raw,updated_at) SELECT ?,?,? WHERE NOT EXISTS(SELECT 1 FROM editor_settings WHERE key='journal_seeded')").bind(pathFor(entry.slug),JSON.stringify(entry),new Date().toISOString())),db.prepare("INSERT OR IGNORE INTO editor_settings(key,value) VALUES('journal_seeded','1')")]);}
function presentJournalRow(row){const data=JSON.parse(row.raw);const original=initialJournal.find(entry=>pathFor(entry.slug)===row.path);if(original&&legacyCovers.includes(data.image))data.image=original.image;return {data:JSON.stringify(data),file:{path:row.path,id:row.path}};}
async function entries(db){await seed(db);const result=await db.prepare('SELECT path,raw FROM journal_entries ORDER BY updated_at DESC').all();return result.results.map(presentJournalRow);}
async function publicEntries(db){return (await entries(db)).map(entry=>JSON.parse(entry.data)).filter(entry=>entry.published!==false).sort((a,b)=>new Date(b.date)-new Date(a.date));}
async function editor(request,env){let id=request.headers.get('oai-authenticated-user-id');let email=request.headers.get('oai-authenticated-user-email');if(env.LOCAL_PREVIEW===true){id='local-preview-editor';email='editor@aurea.local';}if(!id)throw Object.assign(new Error('Sign in as the site owner to use the Journal editor.'),{status:401});await env.DB.prepare("INSERT OR IGNORE INTO editor_settings(key,value) VALUES('editor_user_id',?)").bind(id).run();const account=await env.DB.prepare("SELECT value FROM editor_settings WHERE key='editor_user_id'").first();if(account?.value!==id)throw Object.assign(new Error('This Journal has one assigned editor account.'),{status:403});return {name:'Auréa Journal Editor',login:id,email:email||'',token:''};}
function writeOrigin(request){const origin=request.headers.get('Origin');if(origin!==new URL(request.url).origin)throw Object.assign(new Error('Please submit from this website.'),{status:403});if(!request.headers.get('Content-Type')?.includes('application/json'))throw Object.assign(new Error('JSON input is required.'),{status:415});}
async function input(request){const raw=await request.text();if(raw.length>35000)throw Object.assign(new Error('The request is too large.'),{status:413});try{return JSON.parse(raw);}catch{throw Object.assign(new Error('Invalid request data.'),{status:400});}}
function validArticle(raw,path){if(!safePath(path))throw new Error('Invalid Journal path.');const entry=JSON.parse(raw);entry.slug=path.split('/').pop().replace(/\.json$/,'');if(typeof entry.title!=='string'||entry.title.length<3||entry.title.length>140||typeof entry.excerpt!=='string'||entry.excerpt.length>500||typeof entry.body!=='string'||entry.body.length>25000||!Number.isFinite(new Date(entry.date).getTime())||!covers.includes(entry.image))throw new Error('Please complete the title, date, excerpt, cover and article.');entry.published=entry.published!==false;entry.category=String(entry.category||'Scent Stories').slice(0,60);return JSON.stringify(entry);}
async function api(request,env,url){const db=env.DB;if(!db)throw new Error('Database binding is unavailable.');
 if(url.pathname==='/api/journal'&&request.method==='GET')return json({entries:await publicEntries(db)});
 if(url.pathname.startsWith('/api/editor/')){const account=await editor(request,env);if(url.pathname==='/api/editor/session')return json(account);if(url.pathname==='/api/editor/entries'&&request.method==='GET')return json({entries:await entries(db)});if(url.pathname==='/api/editor/entry'&&request.method==='GET'){const path=url.searchParams.get('path');if(!safePath(path||''))return json({error:'Invalid path'},400);await seed(db);const row=await db.prepare('SELECT path,raw FROM journal_entries WHERE path=?').bind(path).first();return row?json(presentJournalRow(row)):json({error:'Article not found'},404);}if(url.pathname==='/api/editor/media')return json({media:covers.map(path=>({name:path.split('/').pop(),id:path,path,url:path,displayURL:path}))});
 writeOrigin(request);const body=await input(request);
 if(url.pathname==='/api/editor/entry'&&request.method==='POST'){await seed(db);if(!Array.isArray(body.dataFiles)||body.dataFiles.length!==1)return json({error:'Save one Journal entry at a time.'},400);const file=body.dataFiles[0];try{const path=file.newPath||file.path;const raw=validArticle(file.raw,path);const writes=[db.prepare('INSERT INTO journal_entries(path,raw,updated_at) VALUES(?,?,?) ON CONFLICT(path) DO UPDATE SET raw=excluded.raw,updated_at=excluded.updated_at').bind(path,raw,new Date().toISOString())];if(file.newPath&&file.path!==file.newPath&&safePath(file.path))writes.push(db.prepare('DELETE FROM journal_entries WHERE path=?').bind(file.path));await db.batch(writes);return json({ok:true});}catch(error){return json({error:error.message},400);}}
 if(url.pathname==='/api/editor/entries'&&request.method==='DELETE'){if(!Array.isArray(body.paths)||!body.paths.length||body.paths.length>10||body.paths.some(path=>!safePath(path)))return json({error:'Invalid Journal paths.'},400);await seed(db);await db.batch(body.paths.map(path=>db.prepare('DELETE FROM journal_entries WHERE path=?').bind(path)));return json({ok:true});}return json({error:'Editor action not available.'},404);}
 if(url.pathname==='/api/inquiries'&&request.method==='POST'){writeOrigin(request);const body=await input(request);if(body.website)return json({ok:true,message:'Thank you for your inquiry.'});const name=String(body.name||'').trim(),email=String(body.email||'').trim().toLowerCase(),message=String(body.message||'').trim(),interest=String(body.interest||'');if(name.length<2||name.length>80||email.length>120||!/^\S+@\S+\.\S+$/.test(email)||message.length<10||message.length>2000||body.consent!==true||![...fragrances.map(p=>p.id),'recommendation','gift-selection','delivery'].includes(interest))return json({error:'Please complete all fields and agree to share your inquiry details.'},400);const recent=await db.prepare('SELECT COUNT(*) AS count FROM inquiries WHERE email=? AND created_at>?').bind(email,new Date(Date.now()-3600000).toISOString()).first();if(recent.count>=3)return json({error:'Please wait before sending another inquiry.'},429);const now=new Date().toISOString();await db.batch([db.prepare('INSERT INTO inquiries(id,name,email,interest,message,created_at) VALUES(?,?,?,?,?,?)').bind(crypto.randomUUID(),name,email,interest,message,now),db.prepare('INSERT INTO inquiry_actions(id,action,page,created_at) VALUES(?,?,?,?)').bind(crypto.randomUUID(),'form_submission','/contact',now)]);return json({ok:true,message:'Thank you. Your inquiry has been saved for this prototype’s site owner.'},201);}
 if(url.pathname==='/api/actions'&&request.method==='POST'){writeOrigin(request);const body=await input(request);if(body.action!=='contact_button_click'||typeof body.page!=='string'||!/^\/[a-z0-9/-]*$/.test(body.page))return json({error:'Invalid action.'},400);await db.prepare('INSERT INTO inquiry_actions(id,action,page,created_at) VALUES(?,?,?,?)').bind(crypto.randomUUID(),body.action,body.page,new Date().toISOString()).run();return json({ok:true});}return json({error:'Action not found.'},404);
}
export default {async fetch(request,env,ctx){const url=new URL(request.url);try{if(url.pathname.startsWith('/api/'))return await api(request,env,url);if(request.method!=='GET'&&request.method!=='HEAD')return new Response('Method not allowed',{status:405});const path=url.pathname.length>1?url.pathname.replace(/\/$/,''):url.pathname;if(path==='/'||path==='/journal'||path.startsWith('/journal/')){const content=renderPage(path,await publicEntries(env.DB),url.origin);if(content)return new Response(request.method==='HEAD'?null:content,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin'}});}else {const content=renderPage(path,[],url.origin);if(content)return new Response(request.method==='HEAD'?null:content,{headers:{'Content-Type':'text/html; charset=utf-8','X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin'}});}if(path.startsWith('/journal/'))return new Response('This scent story is not available.',{status:404});return await env.ASSETS.fetch(request);}catch(error){return json({error:error.status?error.message:'The request could not be completed. Please try again.'},error.status||500);}}};
